#!/usr/bin/env python3
# THE DEUTERONOMY WALK sitting 12b — THE DOCKET D1 CLOSED: the map's "THE DOCKET — AS RUN (D1)" paragraph appended to the 12b section, the state doc's #205
# ADDENDUM 1 appended, the recovery page's section 2 edited under its cap, the memory index line edited under its cap; EVERY COUNT COMPUTED from the parts on
# disk (never typed); every text built whole before a file is opened; sizes asserted. write_ch14b_cleanpoint.py's form. RUN FROM THE REPO ROOT.
import os, re, sys, subprocess, importlib.util
from collections import Counter
ROOT = subprocess.check_output(['git', 'rev-parse', '--show-toplevel'], text=True).strip()
SP = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, SP)
HOME = os.path.expanduser('~'); MEM = f'{HOME}/.claude/projects/-Users-Shared-TorahSim/memory'
# the counts from the parts
tot = Counter(); n = 0; carried = 0; cells = Counter(); own = {}
for p in 'ABC':
    spec = importlib.util.spec_from_file_location(f'ch14_docket_{p}', f'{SP}/ch14_docket_{p}.py'); m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    tot += Counter(v for _, v, _ in m.ROWS); n += len(m.ROWS); own[p] = len(m.OWN)
    carried += sum(1 for _, _, nt in m.ROWS if nt.startswith('CREDITED (') and '; carried) — ' in nt[:200])
    for _, v, nt in m.ROWS:
        if v == 'LAW' and not nt.startswith('CREDITED ('):
            mm = re.search(r'\b(F[1-7])\b', nt)
            if mm: cells[mm.group(1)] += 1
    assert m.WHOLE_STATS['corrected'] == 0
from ch14_docket_U import OWN_U
U = len(OWN_U); readhere = n - carried; assert readhere == sum(own.values()) + U, (readhere, own, U)
census = ' / '.join(f'{k} {tot[k]}' for k in ('LAW', 'DERIVATION', 'DISPUTE', 'CONTEXT', 'OUTSIDE'))
unc = open(f'{SP}/ch14_docket_uncred.out', encoding='utf-8').read()
split = int(re.search(r'SPLIT_AT \[(\d+)\]', unc).group(1)); assert n == split
chunks = '; '.join(re.findall(r'(ch14_uncred_0[0-2]\.txt rows \d+-\d+ \(\d+ rows, \d+ bytes\))', unc))
carry_line = open(f'{SP}/ch14_credit_carry.out', encoding='utf-8').read().split('\n')[0]
rows = [l.rstrip('\n').split('\t') for l in open(f'{SP}/ch14b_timing.tsv', encoding='utf-8') if l.strip()]
T = '; '.join(f'{name} {secs}s (at {hhmm}, rc {rc})' for hhmm, name, secs, rc in rows if name.startswith('12b D1')); assert T.count(';') >= 4, T
PARA = (f"\nTHE DOCKET — AS RUN (D1) (2026-09-21, on the owner's \"Go\" after the compaction at #205; the timing rows in the scratchpad's ch14b_timing.tsv: {T}): "
 f"THE INSTRUMENTS derived from 11b's forms by asserted substitutions (derive_ch14_docket_tools.py -> ch14_docket_common.py with the cells F1-F7 named, ch14_docket_rows.py, ch14_docket_uncred.py, ch14_credit_survey.py, ch14_credit_carry.py — the unresolved lines led by their dump index so the two runs split them); "
 f"THE RUN BOUNDARY COMPUTED FROM THE DUMP, NEVER TYPED: SPLIT_AT = the first Chullin topic row past folio 66 = row {split}, asserted contiguous — D1 the rows 0-{split - 1} (the 144 link rows; the 88 Mishnah topic rows — two of the design's ninety are link rows, Chullin 8:4 and Avot 3:14; Chullin 59a-66b's 174 topic rows — four of its 178 are link rows), D2 the rows {split}-991 (the seventeen other ranges, Tosefta Peah 4, Tosefta Kilayim 1); "
 f"THE CARRY: {carry_line} (the 289 counts Tosefta Kilayim 1:6 twice — the dump's one duplicate address, a link row and the whole-chapter row; the header's 288); THE CHUNKS: {chunks} — D1's three, each one Read page, EVERY ROW WHOLE; the {U} unresolved credited rows of D1 read whole from ch14_uncred_unres_d1.txt (D2's 31 held in ch14_uncred_unres_d2.txt). "
 f"THE PARTS ON DISK: ch14_docket_A.py (rows 0-143, the link rows — {own['A']} own verdicts), ch14_docket_B.py (rows 144-231, the Mishnah rows — {own['B']}), ch14_docket_C.py (rows 232-405, Chullin 59a-66b — {own['C']}), ch14_docket_U.py (the shared file — {U} unresolved rows read whole here; D2's appended at D2); ch14_d1_check.py (11b's form, the parts named on the command line) GREEN: {n} rows — {census}; {carried} CARRIED with their ledgers' own verdict lines, {readhere} READ WHOLE IN THIS RUN ({sum(own.values())} uncredited and {U} unresolved); the WHOLE dicts empty, apply_whole's counts 0 (no cut to correct); LAW by cell, the own notes {dict(sorted(cells.items()))}. "
 "THE FINDS OF D1 (the crowns, for the ledger's own section at D2): THE BIRDS' SIGNS DERIVED FROM THE TWO POLES AND NAMED THE SAGES' TEACHING (Chullin 61a:1 — the nesher and the dove; Abaye: the signs' explanation is not in the Torah; the ladder 61a:2-61b:7; the twenty-four with four signs 61b:6) with THE RULING one sign and no clawing (62a:4 Ameimar), THE KNOWLEDGE CONDITION (62a:1) and THE TRADITION ARM (63b:11 — a clean bird eaten by tradition, the hunter believed; Tosefta Bekhorot 1:5) — the_birds_signs' value in three layers; THE TWO LISTS COUNTED AT THEIR SEAT (63a:17-63b:2 — Leviticus twenty, Deuteronomy twenty-one, the da'ah and the ra'ah one bird, the ayya and the dayya one; R. Abbahu's twenty-three at 63b:5-7) and their purposes (63b:4, Bekhorot 6b:20 — the beasts' list ADDS the shesua, the birds' EXPLAINS the ra'ah): the reading's diff confirmed by the Gemara's own count; THE FOUR CLOSED BY 'IT' (59a:12, 59a:14 — the school of R. Yishmael) and THE OFFSPRING RULE'S DISPUTE (Bekhorot 6b:2, 7a:7, 7a:20; Tosefta Bekhorot 1:5; Bava Kamma 78a:9 — 'camel, camel' and 'the seh of sheep'); THE TEN NAMED AND NO MORE (Chullin 80a:13) with the wild under the beast's name (71a:2; Zevachim 34a:15) and 'seh' the paradigm (Bava Kamma 77b:13); THE SHESUA A CREATURE (60b:7; Niddah 24a:13 — 'was Moses a hunter?'); THE MONEY'S FORM AT THREE SEATS (Bava Metzia 47b:5 — R. Yishmael the blank, R. Akiva the imprint; Mishnah Eduyot 3:2 — R. Dosa / the Sages; Mishnah Maaser Sheni 1:2 — coined, current, IN ONE'S POSSESSION) with any coinage (Bekhorot 50b:5; Kiddushin 11b:3) and the coined arm applied five times outside (Berakhot 47b:10, Eruvin 31b:12, Pesachim 35b:15, Shabbat 128a:3, Bekhorot 51a:6); THE CLASS FROM THE FOUR NAMED BY GENERAL-PARTICULAR-GENERAL (I6 — Bava Kamma 54b:20; Nazir 35b:3: THE CHAPTER'S VERSE THE SOURCE OF THE METHOD; the rival amplification-restriction at Eruvin 27b:14) with water and salt out (Eruvin 26b:18; Mishnah Eruvin 3:1; Maaser Sheni 1:5) and the containers (Eruvin 27b:3 Ben Bag Bag; Maaser Sheni 1:3-4, 3:12-13); THE WALL AT THE ANSWER SHEET (Maaser Sheni 3:5-7), THE HOUSE STANDING (Temurah 21a:17), the firstling from outside the Land (21b:3), the year passed no bar (Zevachim 29b:2); THE EXILE'S THIRD STATE ON THE TITHE (Maaser Sheni 1:5-6 — no Temple: left to rot, buried with its hide); ONE TITHE NOT TWO AND THE LEVITE NEVER INTERRUPTED (Rosh Hashanah 12b:4); THE ANALOGY BOTH WAYS (Makkot 20a:14; 20a:12 and Kiddushin 36a:6 the whole head) with the measure two hairs (Shabbat 94b:8), the count per soul (Makkot 21a:1), Isi's persons (Kiddushin 35b:16), the sonship's arms (36a:11) and NO FACTIONS (Yevamot 13b:17, 14a:6 — two courts in one town); THE CARCASS DEFINED BY FITNESS FOR A RESIDENT ALIEN (Avodah Zarah 67b:8; Bekhorot 23b:2; Chullin 71a:19), the sale clause the paradigm of a permitted benefit (Kiddushin 56b:10), the sanction a dispute (Yoma 36b:1), the table's first arm (Pesachim 21b:7 — R. Meir both to both); THE KID'S THREE READINGS AT THEIR SEAT (Kiddushin 57b:9) with the benefit counter-arm (57b:10; Bekhorot 10a:2; Menachot 101b:6), the fowl out (Shabbat 130a:11) and the Tosefta's measures (Tosefta Chullin 8:3); THE POOR'S MEASURES (Mishnah Peah 8:5-6) and THE CATTLE TITHE'S ANSWER SHEET with the tenth an ordinal (Mishnah Bekhorot 9:1, 9:7); THE VERSE NO ONE CITES (14:9) READ THROUGH ITS TWIN (Chullin 66b:6-7 — the permission's reach: vessels, pits, ditches and caves; the two sides a command and a ban). "
 "THE DESIGN'S DEPARTURES NOTED FOR RUN B: (a) the class from the four named is I6 by the Gemara's own method (the design wrote I3) — retyped at the types; (b) the_birds_signs' value in THREE LAYERS (the four signs; the ruling with its knowledge condition; the tradition arm) — the parameter's second arm; (c) the_moneys_form's value gains THE POSSESSION CLAUSE (Mishnah Maaser Sheni 1:2; Bava Kamma 98a:4) beside its two arms; (d) second_tithe_owed's value gets THE EXILE'S ARM (no Temple — rot / bury) as chapter 12's slaughter law had; (e) the carcass's sanction carried by sanctions.carcass('lashes_for_eating') by CALL — the dispute a DATA row; (f) the design's 'the ninety Mishnah rows' are 88 topic rows and two link rows, its 'Chullin 59a-66b 178 rows' 174 topic rows and four link rows — the dump's own arithmetic. "
 "NEXT ON HIS WORD (after a compaction: \"Reread\", then \"Go\"): D2 — the rows 406-991 read whole (ch14_uncred_03.txt to ch14_uncred_06.txt; ch14_uncred_unres_d2.txt), the parts D, E, … on disk, ch14_docket_U.py extended, the writer derived from write_ch13_docket.py (the parts 'ABCDE…'; the eighteen ranges asserted against the scan's print; the dump's duplicate address dropped, computed), the ledger written with coverage computed and lint 0, the docket's records (COMPILE_DEBT's box (o), MIDDOT with every code checked before typed, MISHNAH_TOPICS, the state doc's checkpoint), its clean point; then RUN B.\n")
assert not re.search(r'/Users/(?!Shared/)', PARA) and HOME not in PARA and not re.search(r'[֐-׿]', PARA)
MAP = f'{ROOT}/World/step9/DEUTERONOMY_WALK.md'
mp = open(MAP, encoding='utf-8').read()
assert mp.rstrip().split('\n## ')[-1].startswith('Sitting 12b — THE COMPILE OF CHAPTER 14'), 'the map\'s last section is 12b\'s'
MAP_DONE = 'THE DOCKET — AS RUN (D1)' in mp
if not MAP_DONE: open(MAP, 'a', encoding='utf-8').write(PARA)
# 2. the state doc
D = f'{ROOT}/logic/pre_logic_methods_2026-07-28/PROMPT_continue_solo_era_2026-08-06.md'
s = open(D, encoding='utf-8').read(); assert '#205 — NOTE' in s
DONE = '#205 ADDENDUM 1' in s
BLOCK = (f"#205 ADDENDUM 1 (2026-09-21 — THE COMPILE OF CHAPTER 14, sitting 12b: THE DOCKET D1 CLOSED, on the owner's \"Go\" after the compaction at #205; the rereads the recovery page, the map's 12b design (three pages), MEMORY.md, #205 and its NOTE). "
 f"D1 AS RUN (the rows '12b D1' in the scratchpad's ch14b_timing.tsv): the five instruments derived from 11b's forms (derive_ch14_docket_tools.py); THE RUN BOUNDARY COMPUTED from the dump — row {split}, the first Chullin topic row past folio 66, asserted contiguous (D1 rows 0-{split - 1}; D2 rows {split}-991); the carry ({carry_line}); the chunks ({chunks}) read whole, one page each; the {U} unresolved credited rows of D1 read whole; THE PARTS ch14_docket_A.py, _B.py, _C.py and the shared ch14_docket_U.py ON DISK; ch14_d1_check.py GREEN — {n} rows: {census}; {carried} carried, {readhere} read whole in this run; LAW by cell (own notes) {dict(sorted(cells.items()))}. "
 "THE FINDS AND THE DESIGN'S DEPARTURES in the map's \"THE DOCKET — AS RUN (D1)\" paragraph (the newest text of the 12b section): the birds' signs the Sages' teaching in three layers (the four signs, the ruling with its knowledge condition, the tradition arm); the two lists counted at their seat; the four closed by 'it'; the ten named and no more; the money's form at three seats with the possession clause; the class from the four named I6 (the design's I3 retyped at RUN B); the wall, the House standing, the exile's third state on the tithe; one tithe not two; the analogy both ways and no factions; the carcass by fitness, its sanction a dispute; the kid's three readings and the benefit counter-arm; 14:9 read through its twin. "
 "NOT COMMITTED (since fb797a1): sittings 11b and 12 whole, the design, D1's paragraph and this block. NOTHING MID-FLIGHT — A CLEAN COMPACTION POINT (D1's verdicts on disk in the scratchpad; the ledger is written at D2's end by the derived writer over ALL the parts). "
 "NEXT ON HIS WORD (after a compaction: \"Reread\", then \"Go\"): D2 — the rows 406-991 (ch14_uncred_03.txt to _06.txt and ch14_uncred_unres_d2.txt read whole; the parts D, E, …; ch14_docket_U.py extended), the writer derived from write_ch13_docket.py (the eighteen ranges asserted against the scan's print; the duplicate address Tosefta Kilayim 1:6 dropped, computed), the ledger logic/oral_triage/deu_14_reeh_exam_2026-09-21.md with coverage computed and lint 0, the docket's records, its clean point; then RUN B; then THE TAIL. "
 "POST-COMPACTION REREADS: the recovery page, the map's \"Sitting 12b … THE DESIGN\" with its \"THE DOCKET — AS RUN (D1)\" paragraph (the newest section), MEMORY.md.\n")
assert not re.search(r'/Users/(?!Shared/)', BLOCK) and HOME not in BLOCK and not re.search(r'[֐-׿]', BLOCK)
if not DONE: open(D, 'a', encoding='utf-8').write('\n' + BLOCK)
# 3. the recovery page under its cap
P = f'{ROOT}/logic/pre_logic_methods_2026-07-28/RECOVERY_new_thread_2026-09-12.md'
t = open(P, encoding='utf-8').read()
edits = [('## 2. WHERE IT STANDS (2026-09-21, 12b RUN A closed; the state doc #205 the newest)', '## 2. WHERE IT STANDS (2026-09-21, 12b D1 closed; the state doc #205 addendum 1 newest)'),
 ('- NUMBERS CLOSED. DEUTERONOMY 1:1-13:19 COMPILED AND ON THE TAPE (PUSHED through 2b0c9c8); 14 READ AND FROZEN.', '- NUMBERS CLOSED. DEUTERONOMY 1:1-13:19 COMPILED AND ON THE TAPE (PUSHED through 2b0c9c8).'),
 ("- SITTING 12 (ch 14 read and frozen; past the cap — A READING IS TWO RUNS + THE TAIL): 143 sources; 7 claims. 12b RUN A\n  CLOSED — the design in the map (5 lines, 7 writes, 2 reuses, 5 parameters; the docket TWO RUNS).\n- UNCOMMITTED since fb797a1: 13's compile, 14, the design. NEXT ON HIS WORD: the docket D1 (the link rows, Chullin\n  59a-66b, the Mishnah rows), D2, RUN B.",
  f"- SITTING 12 (ch 14 read and frozen): 143 sources; 7 claims. 12b RUN A CLOSED (the design in the map); D1 CLOSED —\n  {n} rows verdicted on disk (parts A-C + the U file in <scratch>; the ledger at D2).\n- UNCOMMITTED since fb797a1: 13's compile, 14, the design. NEXT ON HIS WORD: D2 (rows {split}-991 — the seventeen\n  ranges, Tosefta Peah 4, Kilayim 1), the writer, the records; then RUN B.")]
for a, b in edits:
    assert t.count(a) == 1, a[:70]; t = t.replace(a, b)
assert len(t.encode()) <= 10240, len(t.encode())
# 4. the memory line under 17,000
M = f'{MEM}/MEMORY.md'; mm = open(M, encoding='utf-8').read()
oldm = '12b RUN A CLOSED (the design in the map; the docket TWO runs); 13b + 14 uncommitted; NEXT: the docket D1'
newm = f'12b RUN A + D1 CLOSED (the design; D1 {n} rows on disk); 13b + 14 uncommitted; NEXT: D2, the writer, RUN B'
assert mm.count(oldm) == 1; mm = mm.replace(oldm, newm); assert len(mm.encode()) < 17000, len(mm.encode())
open(P, 'w', encoding='utf-8').write(t); open(M, 'w', encoding='utf-8').write(mm)
print('D1 clean point: the map paragraph', 'appended' if not MAP_DONE else 'already there', len(PARA.encode()), 'bytes | the state doc #205 ADDENDUM 1', 'appended' if not DONE else 'already there', len(BLOCK.encode()), 'bytes | the recovery page', len(t.encode()), '| MEMORY.md', len(mm.encode()))
print('counts:', n, census, '| carried', carried, 'read here', readhere, '| own', own, 'U', U, '| cells', dict(sorted(cells.items())))
